import React, { useState, useEffect, useContext } from 'react';
import { Row, Col, Card, Badge, ProgressBar, Button } from 'react-bootstrap';
import { AuthContext } from '../context/AuthContext';
import api from '../services/api';
import { io } from 'socket.io-client';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, PointElement, LineElement, ArcElement } from 'chart.js';
import { Bar, Line, Doughnut } from 'react-chartjs-2';
import { FaRupeeSign, FaUsers, FaCalendarCheck, FaChartPie, FaBolt, FaArrowUp, FaCheckCircle } from 'react-icons/fa';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, PointElement, LineElement, ArcElement);

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const AdminOverview = () => {
  const { user } = useContext(AuthContext);
  const [sales, setSales] = useState([]);
  const [meetings, setMeetings] = useState([]);
  const [staff, setStaff] = useState([]);
  const [leads, setLeads] = useState([]);
  const [isLive, setIsLive] = useState(true);

  const fetchDashboardData = async () => {
    try {
      const [salesRes, meetRes, staffRes, leadRes] = await Promise.all([
        api.get('/sales'),
        api.get('/meetings'),
        api.get('/admin/staff'),
        api.get('/leads')
      ]);
      setSales(salesRes.data);
      setMeetings(meetRes.data);
      setStaff(staffRes.data);
      setLeads(leadRes.data);
    } catch (err) {
      console.error('Error loading admin overview data:', err);
    }
  };

  useEffect(() => {
    fetchDashboardData();

    const socket = io(process.env.REACT_APP_API_URL || 'http://localhost:5000');
    socket.on('saleAdded', () => fetchDashboardData());
    socket.on('meetingAssigned', () => fetchDashboardData());
    socket.on('meetingAcknowledged', () => fetchDashboardData());
    socket.on('leadAssigned', () => fetchDashboardData());

    return () => socket.disconnect();
  }, []);

  const totalRevenueINR = sales.reduce((acc, curr) => acc + (curr.amountINR || curr.amount || 0), 0);
  const wonSales = sales.filter(s => s.status === 'won' || s.status === 'Won');
  const wonCount = wonSales.length;
  const wonValueINR = wonSales.reduce((acc, curr) => acc + (curr.amountINR || curr.amount || 0), 0);
  const pendingSales = sales.filter(s => s.status === 'pending' || s.status === 'Pending' || s.status === 'New' || s.status === 'Contacted' || s.status === 'Qualified').length;
  const lostSales = sales.filter(s => s.status === 'lost' || s.status === 'Lost').length;

  // Build monthly revenue data from real sales
  const monthlyRevenue = Array(12).fill(0);
  const monthlyWon = Array(12).fill(0);
  sales.forEach(s => {
    const d = new Date(s.createdAt);
    if (!isNaN(d)) {
      const m = d.getMonth();
      monthlyRevenue[m] += (s.amountINR || s.amount || 0);
      if (s.status === 'won' || s.status === 'Won') {
        monthlyWon[m] += (s.amountINR || s.amount || 0);
      }
    }
  });

  // Show last 6 months dynamically
  const now = new Date();
  const last6 = Array.from({ length: 6 }, (_, i) => {
    const idx = (now.getMonth() - 5 + i + 12) % 12;
    return { label: MONTHS[idx], revenue: monthlyRevenue[idx], won: monthlyWon[idx] };
  });

  const revenueChartData = {
    labels: last6.map(m => m.label),
    datasets: [
      {
        label: 'Total Revenue (INR ₹)',
        data: last6.map(m => m.revenue),
        backgroundColor: 'rgba(92, 80, 230, 0.85)',
        borderRadius: 8,
      },
      {
        label: 'Won Value (INR ₹)',
        data: last6.map(m => m.won),
        backgroundColor: 'rgba(16, 185, 129, 0.8)',
        borderRadius: 8,
      }
    ]
  };

  const revenueChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: true, position: 'top', labels: { font: { size: 11 } } },
      tooltip: {
        callbacks: {
          label: (context) => ` ${context.dataset.label}: ₹${context.raw.toLocaleString('en-IN')}`
        }
      }
    },
    scales: {
      x: { grid: { display: false } },
      y: {
        grid: { color: '#f1f5f9' },
        ticks: {
          callback: (v) => `₹${(v / 1000).toFixed(0)}k`
        }
      }
    }
  };

  // Pipeline Doughnut Chart — real data
  const pipelineData = {
    labels: ['Won Deals', 'Active Leads', 'Lost Deals'],
    datasets: [
      {
        data: [wonCount || 0, pendingSales || 0, lostSales || 0],
        backgroundColor: ['#10b981', '#f59e0b', '#ef4444'],
        borderWidth: 0,
      }
    ]
  };

  // Staff performance: top 5 by revenue
  const staffPerformance = staff.map(s => {
    const staffSales = sales.filter(sl => sl.createdBy?._id === s._id || sl.createdBy === s._id || sl.assignedTo?._id === s._id || sl.assignedTo === s._id);
    const revenue = staffSales.reduce((a, b) => a + (b.amountINR || b.amount || 0), 0);
    const won = staffSales.filter(sl => sl.status === 'won' || sl.status === 'Won').length;
    return { ...s, revenue, won, dealsCount: staffSales.length };
  }).sort((a, b) => b.revenue - a.revenue).slice(0, 5);

  const maxRevenue = staffPerformance[0]?.revenue || 1;

  return (
    <div>
      {/* Top Header Banner */}
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h3 className="fw-bold mb-1">Central Admin Dashboard ⚡</h3>
          <p className="text-muted small mb-0">Real-time metrics, live revenue tracking in INR (₹), and staff monitoring.</p>
        </div>
        <div className="d-flex align-items-center gap-2 bg-success-subtle text-success px-3 py-2 rounded-pill fw-semibold small">
          <span className="live-dot"></span> Real-time Socket Live
        </div>
      </div>

      {/* Metric Cards Row */}
      <Row className="g-4 mb-4">
        <Col lg={3} md={6}>
          <Card className="crm-card p-3">
            <div className="d-flex align-items-center gap-3">
              <div className="d-flex align-items-center justify-content-center bg-success-subtle text-success rounded-circle" style={{ width: '52px', height: '52px', fontSize: '24px' }}>
                ₹
              </div>
              <div>
                <div className="text-muted small fw-semibold text-uppercase">Total Revenue (INR)</div>
                <h4 className="fw-bold mb-0">₹{totalRevenueINR.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</h4>
              </div>
            </div>
          </Card>
        </Col>

        <Col lg={3} md={6}>
          <Card className="crm-card p-3">
            <div className="d-flex align-items-center gap-3">
              <div className="d-flex align-items-center justify-content-center bg-emerald-subtle text-success rounded-circle" style={{ width: '52px', height: '52px', fontSize: '22px' }}>
                🏆
              </div>
              <div>
                <div className="text-muted small fw-semibold text-uppercase">Won Value (INR)</div>
                <h4 className="fw-bold mb-0 text-success">₹{wonValueINR.toLocaleString('en-IN')}</h4>
                <div className="text-muted" style={{ fontSize: '11px' }}>{wonCount} deals closed</div>
              </div>
            </div>
          </Card>
        </Col>

        <Col lg={3} md={6}>
          <Card className="crm-card p-3">
            <div className="d-flex align-items-center gap-3">
              <div className="d-flex align-items-center justify-content-center bg-primary-subtle text-primary rounded-circle" style={{ width: '52px', height: '52px', fontSize: '22px' }}>
                <FaUsers />
              </div>
              <div>
                <div className="text-muted small fw-semibold text-uppercase">Active Staff Team</div>
                <h4 className="fw-bold mb-0">{staff.length} Active Members</h4>
              </div>
            </div>
          </Card>
        </Col>

        <Col lg={3} md={6}>
          <Card className="crm-card p-3">
            <div className="d-flex align-items-center gap-3">
              <div className="d-flex align-items-center justify-content-center bg-warning-subtle text-warning rounded-circle" style={{ width: '52px', height: '52px', fontSize: '22px' }}>
                <FaCalendarCheck />
              </div>
              <div>
                <div className="text-muted small fw-semibold text-uppercase">Assigned Meetings</div>
                <h4 className="fw-bold mb-0">{meetings.length} Scheduled</h4>
              </div>
            </div>
          </Card>
        </Col>
      </Row>

      {/* Main Grid Charts */}
      <Row className="g-4 mb-4">
        {/* Monthly Revenue Bar Chart */}
        <Col lg={7} md={12}>
          <Card className="crm-card p-4">
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div>
                <h6 className="fw-bold mb-0">Monthly Revenue vs Won (INR ₹)</h6>
                <div className="text-muted" style={{ fontSize: '11px' }}>Last 6 months — real data from CRM</div>
              </div>
              <Badge bg="primary" className="px-3 py-2 rounded-pill">Monthly Trends</Badge>
            </div>
            <div style={{ height: '240px' }}>
              <Bar data={revenueChartData} options={revenueChartOptions} />
            </div>
          </Card>
        </Col>

        {/* Sales Pipeline Doughnut */}
        <Col lg={5} md={12}>
          <Card className="crm-card p-4">
            <div className="d-flex justify-content-between align-items-center mb-3">
              <h6 className="fw-bold mb-0">Deal Conversion Pipeline</h6>
              <span className="text-muted small">Real-time</span>
            </div>
            <div className="d-flex align-items-center justify-content-center" style={{ height: '200px' }}>
              <Doughnut data={pipelineData} options={{ maintainAspectRatio: false }} />
            </div>
            <div className="d-flex justify-content-center gap-3 mt-3 small">
              <span className="text-success fw-semibold">• Won ({wonCount}) ₹{wonValueINR.toLocaleString('en-IN')}</span>
              <span className="text-warning fw-semibold">• Active ({pendingSales})</span>
              <span className="text-danger fw-semibold">• Lost ({lostSales})</span>
            </div>
          </Card>
        </Col>
      </Row>

      {/* Staff Performance & Recent Activity */}
      <Row className="g-4">
        {/* Staff Performance with Monthly Progress */}
        <Col lg={6}>
          <Card className="crm-card p-4">
            <h6 className="fw-bold mb-3">Staff Performance (Revenue ₹)</h6>
            {staffPerformance.length === 0 ? (
              <div className="text-muted small py-3 text-center">No staff data yet.</div>
            ) : (
              <div className="d-flex flex-column gap-3">
                {staffPerformance.map((s, i) => (
                  <div key={s._id}>
                    <div className="d-flex justify-content-between align-items-center mb-1">
                      <div className="d-flex align-items-center gap-2">
                        <div className="crm-avatar-fallback" style={{ width: '30px', height: '30px', fontSize: '12px' }}>
                          {s.name?.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <div className="fw-semibold small">{s.name}</div>
                          <div className="text-muted" style={{ fontSize: '10px' }}>{s.dealsCount} deals · {s.won} won</div>
                        </div>
                      </div>
                      <span className="fw-bold small text-success">₹{s.revenue.toLocaleString('en-IN')}</span>
                    </div>
                    <ProgressBar
                      now={maxRevenue > 0 ? (s.revenue / maxRevenue) * 100 : 0}
                      style={{ height: '6px', borderRadius: '4px' }}
                      variant={i === 0 ? 'success' : i === 1 ? 'primary' : 'info'}
                    />
                  </div>
                ))}
              </div>
            )}
          </Card>
        </Col>

        {/* Recent Meetings & Activity */}
        <Col lg={6}>
          <Card className="crm-card p-4">
            <h6 className="fw-bold mb-3">Recent Sales Activity Feed (INR ₹)</h6>
            <div className="d-flex flex-column gap-3">
              {sales.length === 0 ? (
                <div className="text-muted small py-3 text-center">No sales entries recorded yet.</div>
              ) : (
                sales.slice(0, 6).map(s => (
                  <div key={s._id} className="d-flex justify-content-between align-items-center border-bottom pb-2">
                    <div>
                      <div className="fw-bold text-dark small">{s.name || s.title || 'Sales Deal'}</div>
                      <div className="text-muted" style={{ fontSize: '11px' }}>
                        By: <strong>{s.createdBy?.name || 'User'}</strong> · {new Date(s.createdAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}
                      </div>
                    </div>
                    <div className="text-end">
                      <div className="fw-bold text-success">₹{(s.amountINR || s.amount || 0).toLocaleString('en-IN')}</div>
                      <Badge bg={s.status === 'won' || s.status === 'Won' ? 'success' : s.status === 'lost' || s.status === 'Lost' ? 'danger' : 'warning'} style={{ fontSize: '10px' }}>{s.status}</Badge>
                    </div>
                  </div>
                ))
              )}
            </div>
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default AdminOverview;
